// DOCUMENTS: the Stage 6 component — a resolver at mini-IP 10.60 holding an
// authoritative name table (example.com -> 10.1) in front of a tick-TTL
// cache. It mirrors the Cache 10.20 ledger pattern: a lookup is a real Map
// probe on the request path, entries carry cachedAtTick/expiresAtTick, and
// an entry past its TTL never answers — the resolver falls through to the
// authoritative table and re-arms the TTL. Deterministic by construction:
// no clock, no RNG — time arrives as the `currentTick` argument.
//
// CHECKS: the constructor rejects an address that is not a two-number
// mini-IP and a ttlTicks that is not a positive integer (fail-loud over
// silent mis-configuration). An unknown name never throws at the DNS layer
// — it answers { status: 'NX' } and the browser renders the NX card; the
// fail-loud throw rule belongs to cross-subnet addresses (network.js).
export function createDns({ address = '10.60', ttlTicks = 300 } = {}) {
  if (!/^\d+\.\d+$/.test(address)) {
    throw new Error(`dns: invalid mini-IP address ${address}`);
  }
  if (!Number.isInteger(ttlTicks) || ttlTicks < 1) {
    throw new Error(`dns: ttlTicks must be a positive integer, got ${ttlTicks}`);
  }
  // Stage 6a authoritative table; Stage 6b adds a CDN name beside it.
  const authoritativeTable = new Map([['example.com', '10.1']]);
  const cache = new Map(); // name -> { name, target, cachedAtTick, expiresAtTick }
  let lookups = 0;
  let cachedHits = 0;
  let authoritative = 0;
  let lastLookup = null;

  // An entry is stale the moment the current tick reaches its expiry:
  // cached at tick T with ttlTicks = 300 means alive through tick T + 299.
  function evictExpired(currentTick = 0) {
    for (const entry of cache.values()) {
      if (currentTick >= entry.expiresAtTick) {
        cache.delete(entry.name);
      }
    }
  }

  // The browser's ask: consult the ledger first; only a miss or an expired
  // entry falls through to the authoritative table (the branch the TTL
  // tests pin — a hit never costs a consult, an expired entry never
  // answers from the ledger).
  function lookup(name, currentTick = 0) {
    lookups += 1;
    evictExpired(currentTick);
    const entry = cache.get(name);
    if (entry) {
      cachedHits += 1;
      lastLookup = { name, status: 'HIT', atTick: currentTick, target: entry.target };
      return { status: 'OK', target: entry.target, source: 'cache' };
    }
    authoritative += 1;
    const target = authoritativeTable.get(name) ?? null;
    if (target === null) {
      lastLookup = { name, status: 'NX', atTick: currentTick };
      return { status: 'NX' };
    }
    cache.set(name, {
      name,
      target,
      cachedAtTick: currentTick,
      expiresAtTick: currentTick + ttlTicks,
    });
    lastLookup = { name, status: 'AUTHORITATIVE', atTick: currentTick, target };
    return { status: 'OK', target, source: 'authoritative' };
  }

  function snapshot(currentTick = 0) {
    evictExpired(currentTick);
    return {
      address,
      ttlTicks,
      lookups,
      cachedHits,
      authoritative,
      lastLookup,
      cache: [...cache.values()].map((e) => ({
        name: e.name,
        target: e.target,
        cachedAtTick: e.cachedAtTick,
        expiresAtTick: e.expiresAtTick,
        ttlRemaining: e.expiresAtTick - currentTick,
      })),
    };
  }

  return {
    get address() {
      return address;
    },
    evictExpired,
    lookup,
    snapshot,
  };
}

// DOCUMENTS: the Stage 6 component — a cross-subnet router joining the
// 10.x and 20.x network instances. Its left interface (10.65) rides the
// 10.x fabric; its right interface (20.1) is registered inside the 20.x
// network as the subnet's gateway, so a frame addressed into 20.x crosses
// in exactly one router hop (routed +1) and the far network's own
// fail-loud rule still applies: an unregistered host (20.9) throws from
// network.js before the hop is counted.
//
// CHECKS: the constructor rejects addresses that are not two-number
// mini-IPs and a router whose two interfaces share one subnet (it would
// not join anything). The gateway itself answers a synchronous send with
// a slim diagnostic — no queue lives behind it, so a queue delivery aimed
// at the gateway fails loud instead of vanishing.
const MINI_IP = /^\d+\.\d+$/;

export function createRouter({ leftAddress = '10.65', rightAddress = '20.1' } = {}) {
  if (!MINI_IP.test(leftAddress)) {
    throw new Error(`router: invalid mini-IP address ${leftAddress}`);
  }
  if (!MINI_IP.test(rightAddress)) {
    throw new Error(`router: invalid mini-IP address ${rightAddress}`);
  }
  if (leftAddress.split('.')[0] === rightAddress.split('.')[0]) {
    throw new Error(
      `router: interfaces must join distinct subnets, got ${leftAddress} and ${rightAddress}`,
    );
  }
  let routed = 0;
  let lastRoute = null;
  let sides = null; // { left, right } — the joined network instances

  function netOf(address) {
    return String(address).split('.')[0];
  }

  // The far network is the one whose subnet owns the destination address.
  function farNetwork(to) {
    if (!sides) throw new Error('router: no networks joined');
    return netOf(to) === netOf(leftAddress) ? sides.left : sides.right;
  }

  return {
    get leftAddress() {
      return leftAddress;
    },
    get rightAddress() {
      return rightAddress;
    },

    // Join the two network instances and stand as the gateway inside the
    // far (20.x) network at the right interface.
    join(left, right) {
      sides = { left, right };
      left.setRouter(this);
      right.setRouter(this);
      right.registerServer(rightAddress, this);
    },

    // One cross-subnet hop: the far network resolves first (unregistered
    // hosts throw before routed counts), then the hop is recorded.
    route({ from, to, request }) {
      const response = farNetwork(to).send({ from, to, request }).response;
      routed += 1;
      lastRoute = { from, to, request };
      return { from, to, request, response };
    },

    // Queue delivery across the subnet boundary; `isYou` rides through
    // untouched, exactly like the same-subnet deliverToQueue contract.
    routeQueue({ id, from, to, request, atTick, isYou = false }) {
      if (to === leftAddress || to === rightAddress) {
        throw new Error(`router: no queue behind the gateway at ${to}`);
      }
      farNetwork(to).deliverToQueue({ id, from, to, request, atTick, isYou });
      routed += 1;
      lastRoute = { from, to, request };
    },

    // The gateway's own slim answer (registered at 20.1 inside the 20.x
    // network) — a diagnostic, not a page: Stage 6b occupies subnet 20
    // with the CDN edge.
    handleRequest() {
      return '200 Router 20.1';
    },

    snapshot() {
      return { leftAddress, rightAddress, routed, lastRoute };
    },
  };
}

// DOCUMENTS: the network — the wiring that lets two-number mini-IP
// addressable components exchange messages. Today it carries slim HTTP
// requests to a registered server; later stages attach more components
// without changing the send/enqueue contract.
//
// Stage 6 adds cross-subnet support additively: a network constructed with
// a `subnet` tag (e.g. '10') hands any frame addressed into a different
// subnet to its attached Router — exactly one router hop, `isYou` rides
// through — and keeps every same-subnet send/deliver byte-identical to
// today's contract. A subnet-less network (Stages 1-5) behaves exactly as
// before: no subnet check, no router.
//
// CHECKS: every address crossing the wire is validated as a two-number
// mini-IP (<net>.<host>), and sends to unregistered hosts fail loud — the
// far network's own fail-loud rule covers cross-subnet frames (20.9 throws
// from the 20.x network before the router hop is counted).
const MINI_IP = /^\d+\.\d+$/;

export function createNetwork({ subnet = null, router = null } = {}) {
  const servers = new Map();
  if (subnet !== null && !/^\d+$/.test(String(subnet))) {
    throw new Error(`network: subnet must be a number, got ${subnet}`);
  }
  const subnetTag = subnet === null ? null : String(subnet);

  function netOf(address) {
    return String(address).split('.')[0];
  }

  function validate(addr) {
    if (!MINI_IP.test(addr)) {
      throw new Error(`network: invalid mini-IP address ${addr}`);
    }
  }

  function resolve(address) {
    validate(address);
    const server = servers.get(address);
    if (!server) {
      throw new Error(`network: no server at ${address}`);
    }
    return server;
  }

  // A frame addressed outside this network's subnet leaves through the
  // router; without an attached router (or without a subnet tag) there is
  // no route and the send fails loud.
  function crossSubnet(message) {
    if (subnetTag === null || !router) {
      throw new Error(`network: no route from ${subnetTag ?? 'this'} subnet to ${message.to}`);
    }
    return router;
  }

  return {
    registerServer(address, server) {
      validate(address);
      servers.set(address, server);
    },

    // Stage 6 wiring: the router attaches itself to both joined networks.
    setRouter(next) {
      router = next;
    },

    resolve,

    send({ from, to, request }) {
      validate(from);
      if (subnetTag !== null && netOf(to) !== subnetTag) {
        return crossSubnet({ to }).route({ from, to, request });
      }
      const server = resolve(to);
      const response = server.handleRequest(request);
      return { from, to, request, response };
    },

    // `isYou` rides through untouched: the engine marks the learner's own
    // interactive-browser request, the server stores it on the queue row.
    deliverToQueue({ id, from, to, request, atTick, isYou = false }) {
      validate(from);
      if (subnetTag !== null && netOf(to) !== subnetTag) {
        crossSubnet({ to }).routeQueue({ id, from, to, request, atTick, isYou });
        return;
      }
      const server = resolve(to);
      server.enqueue({ id, from, to, request, atTick, isYou });
    },
  };
}

