// — the frame narrates what the record did, never a hardcoded story.
export function databaseFrame({ served, database, cache }) {
  const dbOp = served.dbOp ?? null;
  const stale = Boolean(served.dbStale);
  if (dbOp === 'WRITE') {
    return `Database WRITE ${served.request.split(' ')[1]} @ ${database.primaryAddress} (replica ${database.replicaAddress} lags ${database.replicationLagTicks}t)`;
