}
```

Refactor: extract function `stage5HopMaps(snapshot)` → { owners, lanes } (async-aware). Then:

```js
if (snapshot.stage === 5) {
  const { owners, lanes } = stage5HopMaps(snapshot);
  const hop = snapshot.trace?.hop ?? 0;
  return { cardId: owners[hop] ?? 'node-browser', laneId: lanes[hop] ?? 'packet-req-left' };
}
if (snapshot.stage === 6) {
  const t = snapshot.trace ?? {};
  const hop = t.hop ?? 0;
  if (t.dnsStatus === 'NX') {
    const owners = { 1: 'node-browser', 2: 'node-dns' };
    const lanes = { 1: 'packet-req-dns', 2: 'packet-res-dns' };
    return { cardId: owners[hop] ?? 'node-browser', laneId: lanes[hop] ?? 'packet-req-left' };
  }
  if (t.host) {
    const backendCard = t.targetServer === '10.12' ? 'node-webserver-2' : 'node-webserver';
    const dbLane = t.dbOp === 'WRITE' ? 'packet-req-db' : 'packet-res-db';
