input.newString:
// Which card executes the hop, and which wire lane carries it:
// Stage 1 is emit / route / serve / render; Stage 2 inserts the LB's
// round-robin pick; Stage 3 splits the backend serve into the cache
// lookup (Cache 10.20 answers) and the response emission; Stage 4 adds
// the database hop; Stage 5 adds async worker queue processing; Stage 6
// rides two DNS hops (browser ask, resolver answer) in front of the
// Stage 5 map for hosted paths and ends on the NX answer when the name
// has no record.
function stage5HopMaps(snapshot) {
  const backendCard =
    snapshot.trace?.targetServer === '10.12' ? 'node-webserver-2' : 'node-webserver';
  const dbLane = snapshot.trace?.dbOp === 'WRITE' ? 'packet-req-db' : 'packet-res-db';
  const owners = snapshot.trace?.asyncJob
    ? {
        1: 'node-browser',
        2: 'node-network',
        3: 'node-lb',
        4: 'node-queue',
        5: 'node-webserver',
        6: 'node-network',
        7: 'node-browser',
        8: 'node-worker',
      }
    : {
        1: 'node-browser',
        2: 'node-network',
        3: 'node-lb',
        4: 'node-db',
        5: backendCard,
        6: 'node-network',
        7: 'node-browser',
        8: 'node-worker',
      };
  const lanes = snapshot.trace?.asyncJob
    ? {
        1: 'packet-req-left',
        2: 'packet-req-right',
        3: 'packet-req-lb',
        4: 'packet-req-queue',
        5: 'packet-res-cache',
        6: 'packet-res-right',
        7: 'packet-res-left',
        8: 'packet-res-db',
      }
    : {
        1: 'packet-req-left',
        2: 'packet-req-right',
        3: 'packet-req-lb',
        4: dbLane,
        5: 'packet-res-cache',
        6: 'packet-res-right',
        7: 'packet-res-left',
        8: 'packet-res-worker',
      };
  return { owners, lanes };
}

function activeHopTarget(snapshot) {
  const hop = snapshot.trace?.hop ?? 0;
  if (snapshot.stage === 6) {
    const t = snapshot.trace ?? {};
    if (t.dnsStatus === 'NX') {
      const owners = { 1: 'node-browser', 2: 'node-dns' };
      const lanes = { 1: 'packet-req-dns', 2: 'packet-res-dns' };
      return { cardId: owners[hop] ?? 'node-browser', laneId: lanes[hop] ?? 'packet-req-left' };
    }
    if (t.host) {
      // Hosted: the Stage 5 map rides two hops late behind the DNS ask/answer.
      const base = stage5HopMaps(snapshot);
      const owners = { 1: 'node-browser', 2: 'node-dns' };
      const lanes = { 1: 'packet-req-dns', 2: 'packet-res-dns' };
      for (const [k, v] of Object.entries(base.owners)) owners[Number(k) + 2] = v;
      for (const [k, v] of Object.entries(base.lanes)) lanes[Number(k) + 2] = v;
      return { cardId: owners[hop] ?? 'node-browser', laneId: lanes[hop] ?? 'packet-req-left' };
    }
    // Host-less: the Stage 5 map verbatim.
    const base = stage5HopMaps(snapshot);
    return { cardId: base.owners[hop] ?? 'node-browser', laneId: base.lanes[hop] ?? 'packet-req-left' };
  }
  if (snapshot.stage === 5) {
    const base = stage5HopMaps(snapshot);
    return { cardId: base.owners[hop] ?? 'node-browser', laneId: base.lanes[hop] ?? 'packet-req-left' };
  }

