function badgeClass(display) {
  if (!display) return '';
  // A DNS ask's NX answer is not an HTTP status: the badge names the NX
  // verdict (red) instead of printing the parser's NaN (DL-3: the card
  // renders the component's actual message).
  if (String(display.request ?? '').startsWith('ask ')) return ' status-err';
  return display.status >= 200 && display.status < 400 ? ' status-200' : ' status-err';
}

