  workerqueue: {
    file: 'js/sim/queue.js',
    code: `createWorkerQueue({ address = '10.40', workerAddress = '10.41', jobDurationTicks = 2 } = {}) {
  let jobs = [];
  let enqueued = 0;
  let completed = 0;
  let activeJob = null;
  function enqueue(path, payload, currentTick = 0) {
    const jobId = nextJobId++;
    enqueued += 1;
    const job = { jobId, path, payload, status: 'queued', queuedAtTick: currentTick };
    jobs.push(job);
    return job;
  }
  function step(database, currentTick = 0) {
    if (activeJob && currentTick >= activeJob.finishesAtTick) {
      database?.write(activeJob.path, activeJob.payload, currentTick);
      completed += 1;
      activeJob = null;
    }
    if (!activeJob && jobs.length > 0) {
      const job = jobs.shift();
      activeJob = { ...job, status: 'active', startedAtTick: currentTick, finishesAtTick: currentTick + jobDurationTicks };
    }
  }
  return { enqueue, step, snapshot };
}`,
  },
  dns: {
    file: 'js/sim/dns.js',
    code: `createDns({ address = '10.60', ttlTicks = 300 } = {}) {
  // address must be "<net>.<host>" — a two-number mini-IP
  const authoritativeTable = new Map([['example.com', '10.1']]);
  const cache = new Map();  // name -> { target, cachedAtTick, expiresAtTick }
  let lookups = 0, cachedHits = 0, authoritative = 0, lastLookup = null;
  function evictExpired(currentTick = 0) {
    for (const entry of cache.values()) {
      if (currentTick >= entry.expiresAtTick) cache.delete(entry.name);
    }
  }
  function lookup(name, currentTick = 0) {
    lookups += 1;
    evictExpired(currentTick);
    const entry = cache.get(name);
    if (entry) {  // a hit inside ttlTicks never consults the table
      cachedHits += 1;
      lastLookup = { name, status: 'HIT', atTick: currentTick, target: entry.target };
      return { status: 'OK', target: entry.target, source: 'cache' };
    }
    authoritative += 1;
    const target = authoritativeTable.get(name) ?? null;
    if (target === null) {  // NX never throws at the DNS layer
      lastLookup = { name, status: 'NX', atTick: currentTick };
      return { status: 'NX' };
    }
    cache.set(name, { name, target, cachedAtTick: currentTick,
      expiresAtTick: currentTick + ttlTicks });
    lastLookup = { name, status: 'AUTHORITATIVE', atTick: currentTick, target };
    return { status: 'OK', target, source: 'authoritative' };
  }
  function snapshot(currentTick = 0) {
    evictExpired(currentTick);
    return { address, ttlTicks, lookups, cachedHits, authoritative, lastLookup,
      cache: [...cache.values()].map((e) => ({ ...e,
        ttlRemaining: e.expiresAtTick - currentTick })) };
  }
  return { address, evictExpired, lookup, snapshot };
}`,
  },
  router: {
    file: 'js/sim/router.js',
    code: `createRouter({ leftAddress = '10.65', rightAddress = '20.1' } = {}) {
  // both interfaces must be "<net>.<host>" in distinct subnets
  let routed = 0, lastRoute = null, sides = null;
  function farNetwork(to) {  // the network whose subnet owns `to`
    return to.split('.')[0] === leftAddress.split('.')[0] ? sides.left : sides.right;
  }
  return {
    join(left, right) {  // stand as the gateway inside the far network
      sides = { left, right };
      left.setRouter(this);
      right.setRouter(this);
      right.registerServer(rightAddress, this);
    },
    route({ from, to, request }) {  // exactly one cross-subnet hop
      const response = farNetwork(to).send({ from, to, request }).response;
      routed += 1;  // counted only after the far network accepts
      lastRoute = { from, to, request };
