import { describe, it, expect } from 'vitest';
import { createDns } from '../../js/sim/dns.js';
import { createEngine } from '../../js/sim/engine.js';

describe('createDns', () => {
  it('serves a cache hit inside ttlTicks with no authoritative consult, and an expired entry never answers from the ledger', () => {
    const dns = createDns({ address: '10.60', ttlTicks: 300 });

    // Cold ask: the authoritative table answers and arms the ledger at
    // expiresAtTick = 0 + 300.
    expect(dns.lookup('example.com', 0)).toEqual({
      status: 'OK',
      target: '10.1',
      source: 'authoritative',
    });

    // A hit inside the TTL increments cachedHits with NO authoritative
    // consult — the ledger answers by itself.
    expect(dns.lookup('example.com', 299)).toEqual({
      status: 'OK',
      target: '10.1',
      source: 'cache',
    });
    expect(dns.snapshot(299)).toMatchObject({ lookups: 2, cachedHits: 1, authoritative: 1 });

    // CHECKS: the tick the TTL names is the first tick the entry is gone —
    // tick 300 reaches expiresAtTick, the expired entry is evicted and the
    // resolver falls through to the authoritative table (never a stale
    // answer from the ledger, the pinned counter-example).
    expect(dns.lookup('example.com', 300)).toEqual({
      status: 'OK',
      target: '10.1',
      source: 'authoritative',
    });
    const snap = dns.snapshot(300);
    expect(snap).toMatchObject({ lookups: 3, cachedHits: 1, authoritative: 2 });
    expect(snap.cache).toEqual([
      {
        name: 'example.com',
        target: '10.1',
        cachedAtTick: 300,
        expiresAtTick: 600,
        ttlRemaining: 300,
      },
    ]);

    // CHECKS: the constructor rejects a non-mini-IP address and a
    // non-positive or non-integer ttlTicks (fail-loud over silent
    // mis-configuration).
    expect(() => createDns({ address: '1060' })).toThrow(/invalid mini-IP/);
    expect(() => createDns({ ttlTicks: 0 })).toThrow(/ttlTicks/);
    expect(() => createDns({ ttlTicks: 2.5 })).toThrow(/ttlTicks/);
  });

  it('answers NX for an unknown name without ever throwing at the DNS layer', () => {
    const dns = createDns();
    expect(dns.lookup('nope.example', 5)).toEqual({ status: 'NX' });
    const snap = dns.snapshot(5);
    // The table was consulted (authoritative +1) but nothing was cached.
    expect(snap).toMatchObject({ lookups: 1, cachedHits: 0, authoritative: 1 });
    expect(snap.cache).toEqual([]);
    expect(snap.lastLookup).toEqual({ name: 'nope.example', status: 'NX', atTick: 5 });
    // A second ask consults the table again — NX names never enter the ledger.
    expect(dns.lookup('nope.example', 6)).toEqual({ status: 'NX' });
    expect(dns.snapshot(6).authoritative).toBe(2);
  });

  it('stage 6 engine exposes DNS 10.60 and drives its ledger from the hosted trace', () => {
    const engine = createEngine({ stage: 6 });
    let snap = engine.snapshot();
    expect(snap.dns).not.toBe(null);
    expect(snap.dns.address).toBe('10.60');
    expect(snap.dns).toMatchObject({ lookups: 0, cachedHits: 0, authoritative: 0 });
    // Stages 1-5 expose no DNS at all.
    expect(createEngine({ stage: 5 }).snapshot().dns).toBe(null);

    // The hosted trace consults exactly once: ask + answer is one lookup.
    for (let hop = 0; hop < 10; hop++) engine.traceHop({ path: 'example.com/about' });
    snap = engine.snapshot();
    expect(snap.dns).toMatchObject({ lookups: 1, cachedHits: 0, authoritative: 1 });
    expect(snap.dns.cache.map((e) => `${e.name} -> ${e.target}`)).toEqual([
      'example.com -> 10.1',
    ]);

    // The second hosted trace rides the ledger: cachedHits +1, no consult.
    for (let hop = 0; hop < 10; hop++) engine.traceHop({ path: 'example.com/about' });
    snap = engine.snapshot();
    expect(snap.dns).toMatchObject({ lookups: 2, cachedHits: 1, authoritative: 1 });

    // A host-less path never touches the resolver.
    for (let hop = 0; hop < 8; hop++) engine.traceHop({ path: '/about' });
    expect(engine.snapshot().dns).toMatchObject({ lookups: 2, cachedHits: 1, authoritative: 1 });
  });
});

import { describe, it, expect } from 'vitest';
import { createNetwork } from '../../js/sim/network.js';
import { createRouter } from '../../js/sim/router.js';
import { createWebServer } from '../../js/sim/webserver.js';

describe('createRouter + cross-subnet network', () => {
  it('passes same-subnet sends through unchanged and takes exactly one router hop across subnets', () => {
    const router = createRouter({ leftAddress: '10.65', rightAddress: '20.1' });
    const net10 = createNetwork({ subnet: '10', router });
    const net20 = createNetwork({ subnet: '20', router });
    router.join(net10, net20);
    net10.registerServer('10.1', createWebServer({ address: '10.1' }));

    // Same-subnet send: byte-identical to the Stage 1 network contract.
    expect(net10.send({ from: '10.2', to: '10.1', request: 'GET /about' })).toEqual({
      from: '10.2',
      to: '10.1',
      request: 'GET /about',
      response: '200 This is the about page',
    });
    expect(router.snapshot().routed).toBe(0);

    // Cross-subnet: exactly one router hop; the gateway answers its own
    // right interface (nothing lives in subnet 20 in Stage 6a).
    expect(net10.send({ from: '10.2', to: '20.1', request: 'GET /' })).toEqual({
      from: '10.2',
      to: '20.1',
      request: 'GET /',
      response: '200 Router 20.1',
    });
    const snapshot = router.snapshot();
    expect(snapshot.routed).toBe(1);
    expect(snapshot.lastRoute).toEqual({ from: '10.2', to: '20.1', request: 'GET /' });

    // The second crossing increments again — one hop per frame.
    net10.send({ from: '10.2', to: '20.1', request: 'GET /' });
    expect(router.snapshot().routed).toBe(2);

    // CHECKS: the constructor rejects non-mini-IP interfaces and a router
    // whose two interfaces share one subnet (it would join nothing).
    expect(() => createRouter({ leftAddress: '1065' })).toThrow(/invalid mini-IP/);
    expect(() => createRouter({ rightAddress: '201' })).toThrow(/invalid mini-IP/);
    expect(() => createRouter({ leftAddress: '20.65', rightAddress: '20.1' })).toThrow(
      /distinct subnets/,
    );
  });

  it('fails loud on unregistered 20.x hosts before counting a router hop', () => {
    const router = createRouter();
    const net10 = createNetwork({ subnet: '10', router });
    const net20 = createNetwork({ subnet: '20', router });
    router.join(net10, net20);

    // DL-1 fail-loud: 20.9 throws from the far network's own resolve —
    // the named counter-example — and routed stays at 0.
    expect(() => net10.send({ from: '10.2', to: '20.9', request: 'GET /' })).toThrow(
      /no server at 20\.9/,
    );
    expect(router.snapshot().routed).toBe(0);
    expect(router.snapshot().lastRoute).toBe(null);

    // Without an attached router there is no route at all.
    expect(() =>
      createNetwork({ subnet: '10' }).send({ from: '10.2', to: '20.1', request: 'GET /' }),
    ).toThrow(/no route/);
    // And a subnet-less network (Stages 1-5) keeps today's exact behavior.
    const plain = createNetwork();
    plain.registerServer('10.1', createWebServer({ address: '10.1' }));
    expect(() => plain.send({ from: '10.2', to: '20.1', request: 'GET /' })).toThrow(
      /no server at 20\.1/,
    );
    expect(plain.send({ from: '10.2', to: '10.1', request: 'GET /' }).response).toBe(
      '200 Welcome to the home page',
    );
  });

  it('routes queue deliveries with isYou riding through untouched', () => {
    const router = createRouter();
    const net10 = createNetwork({ subnet: '10', router });
    const net20 = createNetwork({ subnet: '20', router });
    router.join(net10, net20);
    const far = createWebServer({ address: '20.5' });
    net20.registerServer('20.5', far);

    // The frame crosses once and enqueues on the far server; isYou rides.
    net10.deliverToQueue({
      id: 'you:3',
      from: '10.2',
      to: '20.5',
      request: 'GET /about',
      atTick: 3,
      isYou: true,
    });
    expect(router.snapshot().routed).toBe(1);
    expect(far.queueSnapshot()).toEqual([
      { id: 'you:3', from: '10.2', to: '20.5', request: 'GET /about', atTick: 3, isYou: true },
    ]);

    // The gateway itself has no queue behind it — fail loud, no hop.
    expect(() =>
      net10.deliverToQueue({
        id: 'you:4',
        from: '10.2',
        to: '20.1',
        request: 'GET /',
        atTick: 4,
        isYou: true,
      }),
    ).toThrow(/no queue behind 20\.1/);
    expect(router.snapshot().routed).toBe(1);
  });
});

