import { describe, it, expect } from 'vitest';
import { describeSnapshot } from '../../js/panel/model.js';
import { formatComponentState } from '../../js/panel/inspector-state.js';

// Stage-boundary narrative pins for Stage 6a (guard-file-size split, as
// with model-stage34/5): the trace narrative branches on the URL shape —
// host-less keeps the Stage 5 story byte-identical, hosted adds exactly
// two DNS hops, and an NX name never emits a GET.
const stage5Snap = {
  stage: 5,
  tick: 1,
  users: 5,
  serverAddress: '10.1',
  queueDepth: 0,
  served: 1,
  avgLatencyTicks: 1,
  workerQueue: {
    address: '10.40',
    workerAddress: '10.41',
    jobDurationTicks: 2,
    enqueued: 0,
    completed: 0,
    activeJob: null,
    pendingJobs: [],
    lastJobResult: null,
  },
  trace: {
    hop: 4,
    method: 'GET',
    path: '/about',
    request: 'GET /about',
    targetServer: '10.11',
    asyncJob: false,
    cacheStatus: 'MISS',
    dbOp: 'SELECT',
    dbStale: true,
    response: '200 This is the about page',
    status: 200,
    body: 'This is the about page',
    routeId: 'about',
    finalHop: 8,
  },
};

const stage6Snap = {
  ...stage5Snap,
  stage: 6,
  dns: {
    address: '10.60',
    ttlTicks: 300,
    lookups: 0,
    cachedHits: 0,
    authoritative: 0,
    lastLookup: null,
    cache: [],
  },
  router: { leftAddress: '10.65', rightAddress: '20.1', routed: 0, lastRoute: null },
};

const hopLabels = (snap, hop, over = {}) =>
  describeSnapshot({ ...snap, trace: { ...snap.trace, hop, ...over } }).hopStatus;

describe('Stage 6 trace narrative branches on the URL shape', () => {
  it('keeps GET /about on Stage 6 at the Stage 5 hop story byte-identical', () => {
    // The named counter-example: a host-less path carries no host, so no
    // DNS hop and no cross-subnet hop may appear — every sentence equals
    // Stage 5's verbatim, denominators included.
    for (let hop = 1; hop <= 8; hop++) {
      expect(hopLabels(stage6Snap, hop)).toBe(hopLabels(stage5Snap, hop));
    }
    expect(hopLabels(stage6Snap, 1)).toBe('Hop 1/8: Browser (10.2) emits "GET /about"');
    expect(hopLabels(stage6Snap, 8)).toBe(
      'Hop 8/8: Worker (10.41) idle — no async jobs in this trace',
    );
  });

  it('rides a hosted path exactly two DNS hops ahead of the Stage 5 story', () => {
    const hosted = {
      ...stage6Snap,
      trace: {
        ...stage6Snap.trace,
        path: '/about',
        request: 'GET /about',
        host: 'example.com',
        dnsStatus: 'OK',
        dnsTarget: '10.1',
        dnsSource: 'authoritative',
        finalHop: 10,
      },
    };
    expect(describeSnapshot(hosted).totalHops).toBe(10);
    expect(hopLabels(hosted, 1)).toBe(
      'Hop 1/10: Browser (10.2) asks DNS (10.60) for "example.com"',
    );
    expect(hopLabels(hosted, 2)).toBe(
      'Hop 2/10: DNS (10.60) -> example.com is 10.1 (authoritative)',
    );
    // The Stage 5 story continues at hop 3, renumbered /10, and ends at
    // hop 10/10 — the two DNS hops are the only additions.
    expect(hopLabels(hosted, 3)).toBe('Hop 3/10: Browser (10.2) emits "GET /about"');
    expect(hopLabels(hosted, 6)).toBe(
      'Hop 6/10: Database SELECT @ Replica (10.31) — STALE (lag 3t)',
    );
    expect(hopLabels(hosted, 10)).toBe(
      'Hop 10/10: Worker (10.41) idle — no async jobs in this trace',
    );
    for (let k = 1; k <= 8; k++) {
      expect(hopLabels(hosted, k + 2)).toBe(
        hopLabels(stage5Snap, k).replace(/^Hop \d\/8:/, `Hop ${k + 2}/10:`),
      );
    }
  });

  it('ends the NX path at hop 2/2 — DNS ask plus NX answer, never a GET', () => {
    const nx = {
      ...stage6Snap,
      trace: {
        ...stage6Snap.trace,
        host: 'nope.example',
        dnsStatus: 'NX',
        dnsTarget: null,
        dnsSource: null,
        finalHop: 2,
      },
    };
    expect(hopLabels(nx, 1)).toBe(
      'Hop 1/2: Browser (10.2) asks DNS (10.60) for "nope.example"',
    );
    expect(hopLabels(nx, 2)).toBe(
      'Hop 2/2: DNS (10.60) -> NX no record for nope.example — browser renders no record',
    );
    // The two-hop story never mentions the GET or a server hop: the whole
    // serialized sentence list leaves "emits" out.
    const sentences = JSON.stringify(describeSnapshot(nx));
    expect(sentences).not.toContain('emits');
    expect(sentences).not.toContain('LoadBalancer');
  });

  it('exposes the DNS ledger and the Router as inspector state and network interfaces', () => {
    const snap = {
      ...stage6Snap,
      dns: {
        address: '10.60',
        ttlTicks: 300,
        lookups: 2,
        cachedHits: 1,
        authoritative: 1,
        lastLookup: { name: 'example.com', status: 'HIT', atTick: 5, target: '10.1' },
        cache: [
          {
            name: 'example.com',
            target: '10.1',
            cachedAtTick: 0,
            expiresAtTick: 300,
            ttlRemaining: 295,
          },
        ],
      },
      router: {
        leftAddress: '10.65',
        rightAddress: '20.1',
        routed: 1,
        lastRoute: { from: '10.2', to: '20.1', request: 'GET /' },
      },
    };
    expect(describeSnapshot(snap).dnsStatsLabel).toBe(
      'Lookups: 2 · Cached hits: 1 · Authoritative: 1',
    );
    expect(describeSnapshot(snap).dnsEntries).toEqual(snap.dns.cache);
    expect(describeSnapshot(snap).routerStatsLabel).toBe('Routed: 1');
    expect(describeSnapshot(snap).routerLastRoute).toBe('10.2 -> 20.1 GET /');
    const dnsState = JSON.parse(formatComponentState(snap, 'dns'));
    expect(dnsState).toEqual({ ...snap.dns });
    const routerState = JSON.parse(formatComponentState(snap, 'router'));
    expect(routerState).toEqual({ ...snap.router });
    // The network table names DNS 10.60 and both Router interfaces.
    const networkState = JSON.parse(formatComponentState(snap, 'network'));
    expect(networkState.interfaces['10.60']).toBe('DNS');
    expect(networkState.interfaces['10.65']).toBe('Router (10.x side)');
    expect(networkState.interfaces['20.1']).toBe('Router (20.x gateway)');
  });
});

import { test, expect } from '@playwright/test';

// Stage 6a — DNS 10.60 (tick-TTL ledger) + cross-subnet Router on its own
// spec (guard-file-size: panel.spec.js sits at its cap). Titles are the
// manifest pins (SIM-6 / PANEL-6): do not reword. The sim runs from a fixed
// seed, so every hop sequence below is identical on every run.
test('should switch to Stage 6, resolve example.com through DNS 10.60, and inspect DNS code + TTL ledger', async ({
  page,
}) => {
  await page.goto('/panel.html');

  await page.getByTestId('stage-pill-6').click();
  await expect(page.getByTestId('stage-pill-6')).toHaveAttribute('aria-current', 'true');
  await expect(page.getByTestId('node-dns')).toBeVisible();
  await expect(page.getByTestId('node-router')).toBeVisible();
  await expect(page.locator('.orrery-ring')).toHaveCount(8);
  await expect(page.locator('.orrery-ring').first()).toHaveAttribute('r', '400');
  await expect(page.locator('.orrery-ring').last()).toHaveAttribute('r', '3200');
  await expect(page.getByTestId('dns-stats')).toHaveText(
    'Lookups: 0 · Cached hits: 0 · Authoritative: 0',
  );
  await expect(page.getByTestId('router-stats')).toHaveText('Routed: 0');

  // First hosted trace: the resolver consults the authoritative table once
  // and warms the ledger (example.com -> 10.1).
  await page.getByTestId('url-input').fill('example.com/about');
  await page.getByTestId('btn-url-go').click();
  await expect(page.getByTestId('dns-stats')).toHaveText(
    'Lookups: 1 · Cached hits: 0 · Authoritative: 1',
  );
  await expect(page.getByTestId('dns-entries-list')).toContainText('example.com -> 10.1');
  await expect(page.getByTestId('browser-rendered-body')).toHaveText('This is the about page');

  // Second hosted trace: the ledger answers inside the TTL — cachedHits +1,
  // no authoritative consult.
  await page.getByTestId('btn-url-go').click();
  await expect(page.getByTestId('dns-stats')).toHaveText(
    'Lookups: 2 · Cached hits: 1 · Authoritative: 1',
  );

  // The resolver's code and live ledger state open in the inspector.
  await page.getByTestId('node-dns').click();
  await expect(page.getByTestId('inspector-code')).toContainText('createDns');
  await expect(page.getByTestId('inspector-state')).toContainText('"ttlTicks": 300');
  await expect(page.getByTestId('inspector-state')).toContainText('"cachedHits": 1');
  await expect(page.getByTestId('inspector-title')).toHaveText('DNS — mini-IP 10.60');
});

test('should trace example.com/about with DNS ask + answer hops', async ({ page }) => {
  await page.goto('/panel.html?stage=6');

  await expect(page.getByTestId('node-dns')).toBeVisible();
  await page.getByTestId('url-input').fill('example.com/about');

  // Hops 1-2/10: the browser asks DNS 10.60 and the resolver answers —
  // before any GET moves (the wire consumes the resolver's actual answer).
  await page.getByTestId('btn-next-hop').click();
  await expect(page.getByTestId('hop-status')).toHaveText(
    'Hop 1/10: Browser (10.2) asks DNS (10.60) for "example.com"',
  );
  await page.getByTestId('btn-next-hop').click();
  await expect(page.getByTestId('hop-status')).toHaveText(
    'Hop 2/10: DNS (10.60) -> example.com is 10.1 (authoritative)',
  );

  // Hop 3/10: only now the resolved GET is emitted toward 10.1.
  await page.getByTestId('btn-next-hop').click();
  await expect(page.getByTestId('hop-status')).toHaveText(
    'Hop 3/10: Browser (10.2) emits "GET /about"',
  );

  // Hops 4-10/10: the Stage 5 journey lands the response.
  for (let hop = 0; hop < 7; hop++) await page.getByTestId('btn-next-hop').click();
  await expect(page.getByTestId('hop-status')).toHaveText(
    'Hop 10/10: Worker (10.41) idle — no async jobs in this trace',
  );
  await expect(page.getByTestId('browser-rendered-body')).toHaveText('This is the about page');
  await expect(page.getByTestId('dns-stats')).toHaveText(
    'Lookups: 1 · Cached hits: 0 · Authoritative: 1',
  );
});

test('should keep GET /about on Stage 6 at the Stage 5 hop story', async ({ page }) => {
  // The named counter-example: a host-less path never touches DNS or the
  // router — its 8-hop story is byte-identical to Stage 5's, denominators
  // included, and the resolver's counters stay at zero.
  await page.goto('/panel.html?stage=6');

  await page.getByTestId('url-input').fill('/about');
  await expect(page.getByTestId('dns-stats')).toHaveText(
    'Lookups: 0 · Cached hits: 0 · Authoritative: 0',
  );
  for (let hop = 0; hop < 8; hop++) await page.getByTestId('btn-next-hop').click();

  await expect(page.getByTestId('hop-status')).toHaveText(
    'Hop 1/8: Browser (10.2) emits "GET /about"',
  );
  // Read the whole journey log: every label reads hop N/8 in ascending
  // order — no /10 renumbering and no DNS ask entry anywhere.
  const labels = await page.getByTestId('journey-log').locator('.journey-entry').allTextContents();
  const hopRows = labels
    .map((text) => text.match(/^(hop \d\/\d)/)?.[1])
    .filter(Boolean)
    .slice(0, 8);
  expect(hopRows).toEqual([
    'hop 1/8',
    'hop 2/8',
    'hop 3/8',
    'hop 4/8',
    'hop 5/8',
    'hop 6/8',
    'hop 7/8',
    'hop 8/8',
  ]);
  await expect(page.getByTestId('dns-stats')).toHaveText(
    'Lookups: 0 · Cached hits: 0 · Authoritative: 0',
  );
  await expect(page.getByTestId('browser-rendered-body')).toHaveText('This is the about page');
});

// Negative-case pin: an unknown name never emits a GET — the trace ends at
// the DNS answer and the browser renders the NX card.
test('should render the NX card for nope.example without emitting a GET', async ({ page }) => {
  await page.goto('/panel.html?stage=6');

  await page.getByTestId('url-input').fill('nope.example/about');
  await page.getByTestId('btn-url-go').click();
  await expect(page.getByTestId('hop-status')).toHaveText(
    'Hop 2/2: DNS (10.60) -> NX no record for nope.example — browser renders no record',
  );
  await expect(page.getByTestId('browser-rendered-body')).toHaveText(
    'no record for nope.example',
  );
  await expect(page.getByTestId('browser-status-badge')).toContainText('NX (ask nope.example)');
  await expect(page.getByTestId('dns-stats')).toHaveText(
    'Lookups: 1 · Cached hits: 0 · Authoritative: 1',
  );
  // No GET ever reached the backends: both queues stay empty.
  await expect(page.getByTestId('server-queue-list')).toContainText('queue empty');
});

// The ?stage= live set extends to 6 with stage-pill-6; unknown values still
// fall back to 1 (the fallback itself is pinned in panel.spec.js ?stage=9).
test('should deep-link ?stage=6 to the live stage with DNS and router cards', async ({
  page,
}) => {
  await page.goto('/panel.html?stage=6&users=7');
  await expect(page.getByTestId('stage-pill-6')).toHaveAttribute('aria-current', 'true');
  await expect(page.getByTestId('node-dns')).toBeVisible();
  await expect(page.getByTestId('node-router')).toBeVisible();
  await expect(page.getByTestId('user-dots').locator('> *')).toHaveCount(7);
  // Clicking the router opens its code and routed counter in the inspector.
  await page.getByTestId('node-router').click();
  await expect(page.getByTestId('inspector-code')).toContainText('createRouter');
  await expect(page.getByTestId('inspector-state')).toContainText('"routed": 0');
  await expect(page.getByTestId('inspector-title')).toHaveText('Router — 10.65 ⇄ 20.1');
});

